class MinStack:
    def __init__(self):
        self.stack = []
        self.mins = []

    def push(self, val):
        self.stack.append(val)
        if not self.mins or val <= self.mins[-1]:
            self.mins.append(val)
        else:
            self.mins.append(self.mins[-1])

    def pop(self):
        self.stack.pop()
        self.mins.pop()

    def top(self):
        return self.stack[-1]

    def getMin(self):
        return self.mins[-1]

def main():
    q = int(input())
    st = MinStack()
    out = []
    for _ in range(q):
        op = input().split()
        if op[0] == "push":
            st.push(int(op[1]))
        elif op[0] == "pop":
            st.pop()
        elif op[0] == "top":
            out.append(str(st.top()))
        else:
            out.append(str(st.getMin()))
    print(*out)


if __name__ == "__main__":
    main()
